begin;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.id(n integer) returns uuid language sql immutable as $$ select ('fd000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid $$;
alter table public.clinics alter constraint clinics_owner_profile_fk deferrable initially deferred;
insert into auth.users(id) select pg_temp.id(n) from generate_series(1,8) n;
insert into public.clinics(id,name,owner_profile_id,makeup_policy) values
 (pg_temp.id(10),'Synthetic stabilization one',pg_temp.id(1),'{"eligible_statuses":["ABSENT_JUSTIFIED"],"no_show_action":"return"}'),
 (pg_temp.id(11),'Synthetic stabilization two',pg_temp.id(8),null);
insert into public.profiles(id,clinic_id,name,role,status) select pg_temp.id(n),case when n=8 then pg_temp.id(11) else pg_temp.id(10) end,'Synthetic role '||n,(array['admin','manager','reception','professional','professional','finance','reception','admin']::public.user_role[])[n],'active' from generate_series(1,8) n;
set constraints clinics_owner_profile_fk immediate;
insert into public.units(id,clinic_id,name) values(pg_temp.id(20),pg_temp.id(10),'Synthetic A'),(pg_temp.id(21),pg_temp.id(10),'Synthetic B'),(pg_temp.id(22),pg_temp.id(11),'Synthetic foreign');
insert into public.profile_units(profile_id,unit_id) values(pg_temp.id(2),pg_temp.id(20)),(pg_temp.id(2),pg_temp.id(21)),(pg_temp.id(3),pg_temp.id(20)),(pg_temp.id(3),pg_temp.id(21)),(pg_temp.id(4),pg_temp.id(20)),(pg_temp.id(5),pg_temp.id(21)),(pg_temp.id(6),pg_temp.id(20)),(pg_temp.id(7),pg_temp.id(20));
insert into public.profile_permissions(profile_id,module,can_view,can_edit)
 select pg_temp.id(n),m,true,true from generate_series(2,6) n cross join unnest(array['agenda','patients','records','finance','enrollments','settings']) m where (n=2 or (n=3 and m in('agenda','patients','enrollments')) or (n in(4,5) and m in('agenda','patients','records')) or (n=6 and m in('finance','enrollments')));
insert into public.professionals(id,clinic_id,profile_id,name) values(pg_temp.id(40),pg_temp.id(10),pg_temp.id(4),'Synthetic primary'),(pg_temp.id(41),pg_temp.id(10),pg_temp.id(5),'Synthetic substitute'),(pg_temp.id(42),pg_temp.id(10),null,'Synthetic parallel');
insert into public.professional_units(professional_id,unit_id) values(pg_temp.id(40),pg_temp.id(20)),(pg_temp.id(41),pg_temp.id(21)),(pg_temp.id(42),pg_temp.id(20));
insert into public.patients(id,clinic_id,primary_unit_id,name) values(pg_temp.id(30),pg_temp.id(10),pg_temp.id(20),'Synthetic patient A'),(pg_temp.id(31),pg_temp.id(10),pg_temp.id(21),'Synthetic patient B'),(pg_temp.id(32),pg_temp.id(10),pg_temp.id(20),'Synthetic patient C');
insert into public.patients(id,clinic_id,primary_unit_id,name) select pg_temp.id(100+n),pg_temp.id(10),pg_temp.id(20),'Synthetic search '||lpad(n::text,3,'0') from generate_series(1,110) n;
insert into public.plans(id,clinic_id,name,kind,duration_days,sessions_included,price_cents) values(pg_temp.id(50),pg_temp.id(10),'Synthetic monthly','monthly',30,8,22000),(pg_temp.id(51),pg_temp.id(10),'Synthetic quarterly','package',90,24,60000);
create temp table ids(key text primary key,id uuid);grant all on ids to authenticated;
create function pg_temp.class_input(pro uuid,u uuid,t time) returns jsonb language sql as $$ select public.create_class_with_schedule(u,'Synthetic class',null,'active',current_date,array['monday','tuesday','wednesday','thursday','friday','saturday','sunday']::public.class_weekday[],t,t+interval '1 hour','America/Sao_Paulo',pro,1,null) $$;
select set_config('request.jwt.claim.sub',pg_temp.id(1)::text,true);set local role authenticated;
select lives_ok($$insert into ids values('classA',(pg_temp.class_input(pg_temp.id(40),pg_temp.id(20),'08:00')->'class'->>'id')::uuid)$$,'J01 create class and recurring occurrences atomically');
select lives_ok($$select public.ensure_calendar_window(pg_temp.id(20),current_date,current_date+7)$$,'J05 repeated calendar generation is idempotent');
select lives_ok($$insert into ids values('classParallel',(pg_temp.class_input(pg_temp.id(42),pg_temp.id(20),'08:00')->'class'->>'id')::uuid)$$,'J01 different professionals share time/unit');
select throws_ok($$select pg_temp.class_input(pg_temp.id(40),pg_temp.id(20),'08:30')$$,'P0001','PROFESSIONAL_SCHEDULE_CONFLICT','J01 same professional overlap rejected');
select is((select count(*) from public.classes),2::bigint,'J01 failed compound create leaves no orphan');
select lives_ok($$insert into ids values('classB',(pg_temp.class_input(pg_temp.id(41),pg_temp.id(21),'09:00')->'class'->>'id')::uuid)$$,'J01 another unit schedule');
select lives_ok($$insert into ids values('makeup',(pg_temp.class_input(pg_temp.id(41),pg_temp.id(21),'11:00')->'class'->>'id')::uuid)$$,'J03 concrete makeup class');
select lives_ok($$insert into ids values('makeup2',(pg_temp.class_input(pg_temp.id(42),pg_temp.id(20),'12:00')->'class'->>'id')::uuid)$$,'J03 alternative makeup');
insert into ids select 'todayA',id from public.class_occurrences where class_id=(select id from ids where key='classA') and local_date=current_date;
insert into ids select 'todayMakeup',id from public.class_occurrences where class_id=(select id from ids where key='makeup') and local_date=current_date;
insert into ids select 'todayMakeup2',id from public.class_occurrences where class_id=(select id from ids where key='makeup2') and local_date=current_date;
insert into ids select 'tomorrowMakeup',id from public.class_occurrences where class_id=(select id from ids where key='makeup') and local_date=current_date+1;
select lives_ok($$select public.save_operational_membership((select id from ids where key='classA'),pg_temp.id(30),current_date,null,array['monday','tuesday','wednesday','thursday','friday','saturday','sunday']::public.class_weekday[])$$,'J01 add patient A');
select lives_ok($$select public.save_operational_membership((select id from ids where key='classA'),pg_temp.id(32),current_date,null,array['monday','tuesday','wednesday','thursday','friday','saturday','sunday']::public.class_weekday[])$$,'RN006 informational capacity does not block second participant');
select is((select count(*) from public.effective_occurrence_patient_ids((select id from ids where key='todayA'))),2::bigint,'J02 effective roster includes both');
select throws_ok($$select public.save_operational_membership((select id from ids where key='classParallel'),pg_temp.id(30),current_date,null,array['monday']::public.class_weekday[])$$,'P0001','PATIENT_SCHEDULE_CONFLICT','J01 recurring patient conflict is rejected beyond materialization horizon');
select lives_ok($$select public.save_operational_membership((select id from ids where key='classB'),pg_temp.id(30),current_date,null,array['monday','tuesday','wednesday','thursday','friday','saturday','sunday']::public.class_weekday[])$$,'J01 same patient can attend another unit at a different time');
select throws_ok($$insert into public.appointments(clinic_id,unit_id,professional_id,starts_at,ends_at,status) values(pg_temp.id(10),pg_temp.id(20),pg_temp.id(40),(current_date+time '08:00') at time zone 'America/Sao_Paulo',(current_date+time '09:00') at time zone 'America/Sao_Paulo','blocked')$$,'P0001','PROFESSIONAL_SCHEDULE_CONFLICT','J01 appointment conflicts with Class professional');
select throws_ok($$insert into public.appointments(clinic_id,unit_id,professional_id,patient_id,starts_at,ends_at,status) values(pg_temp.id(10),pg_temp.id(21),pg_temp.id(41),pg_temp.id(30),(current_date+time '08:00') at time zone 'America/Sao_Paulo',(current_date+time '09:00') at time zone 'America/Sao_Paulo','scheduled')$$,'P0001','PATIENT_SCHEDULE_CONFLICT','J01 appointment conflicts with Class patient across units');
select is((select count(*) from public.patients where name like 'Synthetic search %'),110::bigint,'more than 100 authorized patients are queryable');
select is((select count(*) from (select id from public.patients where name like 'Synthetic search %' order by name offset 100 limit 100) p),10::bigint,'second page contains remaining patients');
select lives_ok($$select public.save_occurrence_attendance((select id from ids where key='todayA'),pg_temp.id(30),'ABSENT_JUSTIFIED',null,null,'Synthetic notice')$$,'J02 record justified absence');
insert into ids select 'creditA',a.id from public.attendances a join public.occurrence_participants p on p.id=a.occurrence_participant_id where p.class_occurrence_id=(select id from ids where key='todayA') and p.patient_id=pg_temp.id(30);
select is((select makeup_state from public.attendances where id=(select id from ids where key='creditA')),'eligible','J03 configured policy creates eligible credit');
select lives_ok($$select public.save_occurrence_attendance((select id from ids where key='todayA'),pg_temp.id(30),'ABSENT_JUSTIFIED',null,1,'Synthetic notice')$$,'J02 repeated attendance is idempotent');
select is((select version from public.attendances where id=(select id from ids where key='creditA')),1,'J02 retry preserves version');
select throws_ok($$select public.save_occurrence_attendance((select id from ids where key='todayA'),pg_temp.id(30),'PRESENT',null,1,'Synthetic notice')$$,'P0001','ATTENDANCE_CORRECTION_REASON_REQUIRED','J02 correction requires reason');
select set_config('request.jwt.claim.sub',pg_temp.id(4)::text,true);
select lives_ok($$select public.save_occurrence_attendance((select id from ids where key='todayA'),pg_temp.id(30),'PRESENT','Synthetic correction',1,'Synthetic notice')$$,'J02 responsible professional may correct own attendance');
select is((select makeup_state from public.attendances where id=(select id from ids where key='creditA')),'none','J03 correcting unused absence removes credit eligibility');
select throws_ok($$select public.save_occurrence_attendance((select id from ids where key='todayA'),pg_temp.id(30),'ABSENT_JUSTIFIED','Stale correction',1,'Synthetic notice')$$,'P0001','ATTENDANCE_VERSION_CONFLICT','J02 stale concurrent correction rejected');
select set_config('request.jwt.claim.sub',pg_temp.id(3)::text,true);
select lives_ok($$select public.save_occurrence_attendance((select id from ids where key='todayA'),pg_temp.id(30),'ABSENT_JUSTIFIED','Reception correction',2,'Synthetic notice')$$,'J02 reception may correct with history');
select is((select count(*) from public.attendance_revisions where attendance_id=(select id from ids where key='creditA')),2::bigint,'J02 both corrections persist history');
select lives_ok($$select public.update_class_occurrence((select id from ids where key='todayMakeup'),'11:00','12:00',pg_temp.id(40),null)$$,'J04 substitution can use a professional from another habitual unit');
select is((select planned_professional_id from public.class_occurrences where id=(select id from ids where key='todayMakeup')),pg_temp.id(41),'J04 planned professional stays in history');
select set_config('request.jwt.claim.sub',pg_temp.id(4)::text,true);
select lives_ok($$select public.get_occurrence_attendance_details((select id from ids where key='todayMakeup'))$$,'J04 cross-unit substitute can open the assigned occurrence');
select throws_ok($$select public.get_occurrence_attendance_details((select id from ids where key='tomorrowMakeup'))$$,'P0001','CLASS_OCCURRENCE_NOT_FOUND','J04 substitute has no access to unrelated occurrence');
select set_config('request.jwt.claim.sub',pg_temp.id(3)::text,true);
select lives_ok($$select public.manage_makeup_credit((select id from ids where key='creditA'),'reserve',(select id from ids where key='todayMakeup'))$$,'J03 reserve credit atomically');
select is((select makeup_state from public.attendances where id=(select id from ids where key='creditA')),'reserved','J03 reservation does not consume credit');
select lives_ok($$select public.manage_makeup_credit((select id from ids where key='creditA'),'reserve',(select id from ids where key='todayMakeup'))$$,'J03 retry reservation is idempotent');
select throws_ok($$select public.manage_makeup_credit((select id from ids where key='creditA'),'reserve',(select id from ids where key='todayMakeup2'))$$,'P0001','MAKEUP_CREDIT_UNAVAILABLE','J03 duplicate credit use rejected');
select lives_ok($$select public.save_occurrence_attendance((select id from ids where key='todayMakeup'),pg_temp.id(30),'PRESENT')$$,'J03 record actual makeup presence');
select is((select makeup_state from public.attendances where id=(select id from ids where key='creditA')),'consumed','J03 only confirmed presence consumes credit');
select throws_ok($$select public.save_occurrence_attendance((select id from ids where key='todayA'),pg_temp.id(30),'PRESENT','Already consumed correction',3,'Synthetic notice')$$,'P0001','MAKEUP_CREDIT_IN_USE','J03 consumed source cannot be silently rewritten');
select lives_ok($$select public.save_occurrence_attendance((select id from ids where key='todayA'),pg_temp.id(32),'ABSENT_JUSTIFIED')$$,'J03 second justified absence');
insert into ids select 'creditC',a.id from public.attendances a join public.occurrence_participants p on p.id=a.occurrence_participant_id where p.class_occurrence_id=(select id from ids where key='todayA') and p.patient_id=pg_temp.id(32);
select lives_ok($$select public.manage_makeup_credit((select id from ids where key='creditC'),'reserve',(select id from ids where key='tomorrowMakeup'))$$,'J03 reserve another credit');
select lives_ok($$select public.manage_makeup_credit((select id from ids where key='creditC'),'return',null,'Synthetic cancellation return')$$,'J03 cancellation returns reserved credit with reason');
select is((select count(*) from public.effective_occurrence_patient_ids((select id from ids where key='tomorrowMakeup'))),0::bigint,'J03 cancellation removes only the replacement participant');
select lives_ok($$select public.manage_makeup_credit((select id from ids where key='creditC'),'reserve',(select id from ids where key='todayMakeup2'))$$,'J03 returned credit can be booked again');
select lives_ok($$select public.save_occurrence_attendance((select id from ids where key='todayMakeup2'),pg_temp.id(32),'ABSENT_UNJUSTIFIED')$$,'J03 record no-show at makeup');
select is((select makeup_state from public.attendances where id=(select id from ids where key='creditC')),'eligible','J03 no-show uses explicitly configured policy');
select lives_ok($$select public.save_agenda_exception('holiday',pg_temp.id(20),null,((current_date+1)+time '00:00') at time zone 'America/Sao_Paulo',((current_date+2)+time '00:00') at time zone 'America/Sao_Paulo','Synthetic closure')$$,'J05 holiday cancels tomorrow across authorized units');
select is((select count(*) from public.class_occurrences where local_date=current_date+1 and status<>'cancelled'),0::bigint,'J05 holiday persisted state is closed');
select is((select count(*) from public.attendances where makeup_state='eligible'),1::bigint,'J05 holiday did not generate attendance or automatic credit');
select lives_ok($$select public.ensure_calendar_window(pg_temp.id(20),current_date+56,current_date+60)$$,'J05 occurrence generation continues beyond initial horizon');
select set_config('request.jwt.claim.sub',pg_temp.id(7)::text,true);
select is((select count(*) from public.classes),0::bigint,'denied agenda grants hide Class rows');
select throws_ok($$select public.ensure_calendar_window(pg_temp.id(20),current_date,current_date+1)$$,'P0001','FORBIDDEN','denied agenda grants block RPC');
select set_config('request.jwt.claim.sub',pg_temp.id(8)::text,true);
select is((select count(*) from public.class_occurrences),0::bigint,'cross-clinic occurrence isolation');
select is((select count(*) from public.patients where clinic_id=pg_temp.id(10)),0::bigint,'cross-clinic patient isolation');
select set_config('request.jwt.claim.sub',pg_temp.id(6)::text,true);
select lives_ok($$insert into ids values('enrollment',(public.save_enrollment(jsonb_build_object('patient_id',pg_temp.id(30),'plan_id',pg_temp.id(50),'unit_id',pg_temp.id(20),'starts_at',date_trunc('month',current_date)::date,'due_day',5),gen_random_uuid())).id)$$,'J06 create financial contract');
select is((select contract_amount_cents from public.enrollments where id=(select id from ids where key='enrollment')),22000,'J06 new contract preserves the approved price snapshot');
insert into ids select 'charge',id from public.charges where enrollment_id=(select id from ids where key='enrollment');
select lives_ok($$select public.register_payment((select id from ids where key='charge'),10000,'pix',date_trunc('day',now()),'synthetic-partial',gen_random_uuid())$$,'J06 partial payment');
select is((select paid_cents from public.charges where id=(select id from ids where key='charge')),10000,'J06 actual persisted receipt accumulator');
select is((select status::text from public.charges where id=(select id from ids where key='charge')),'partial','J06 partial is not marked paid');
select lives_ok($$select public.register_payment((select id from ids where key='charge'),10000,'pix',date_trunc('day',now()),'synthetic-partial',gen_random_uuid())$$,'J06 receipt retry is idempotent');
select is((select count(*) from public.payments),1::bigint,'J06 no duplicate receipt');
select throws_ok($$select public.register_payment((select id from ids where key='charge'),10001,'pix',date_trunc('day',now()),'synthetic-partial',gen_random_uuid())$$,'P0001','IDEMPOTENCY_CONFLICT','J06 reused key cannot change amount');
select lives_ok($$select public.register_payment((select id from ids where key='charge'),12000,'cash',date_trunc('day',now()),'synthetic-final',gen_random_uuid())$$,'J06 mixed-method final payment');
select is((select status::text from public.charges where id=(select id from ids where key='charge')),'paid','J06 paid requires complete actual receipt');
select is((select sum(amount_cents) from public.payments where reversed_at is null),22000::bigint,'J06 receipt sum equals due');
select throws_ok($$update public.financial_entries set deleted_at=now() where payment_id is not null$$,'P0001','PAYMENT_LEDGER_IMMUTABLE','J06 deleting a receipt ledger is rejected');
select throws_ok($$select public.rollback_enrollment((select id from ids where key='enrollment'),'Synthetic rollback with receipts',gen_random_uuid())$$,'P0001','ENROLLMENT_HAS_PAYMENTS','J06 rollback preserves received contract');
select is((select count(*) from public.clinical_records),0::bigint,'finance cannot read clinical records');
select throws_ok($$select public.save_professional('{"name":"Synthetic forbidden","unitIds":["fd000000-0000-4000-8000-000000000020"]}')$$,'P0001','FORBIDDEN','finance cannot manage clinical professionals');
select set_config('request.jwt.claim.sub',pg_temp.id(1)::text,true);
select lives_ok($$select public.update_operational_group((select id from ids where key='classParallel'),jsonb_build_object('effective_from',current_date+3,'starts_at','10:00','duration_minutes',60,'professional_id',pg_temp.id(42),'capacity',1))$$,'J05 permanent time change starts at explicit future date');
select is((select count(*) from public.class_schedules where class_id=(select id from ids where key='classParallel')),2::bigint,'J05 schedule history retains both versions');
select is((select local_start_time from public.class_occurrences where class_id=(select id from ids where key='classParallel') and local_date=current_date+2 and status='planned'),time '08:00','J05 earlier occurrence keeps original time');
insert into ids select 'point',id from public.class_occurrences where class_id=(select id from ids where key='classParallel') and local_date=current_date+4 and status='planned';
select lives_ok($$select public.reschedule_class_occurrence((select id from ids where key='point'),current_date+5,'14:00','15:00',pg_temp.id(42),null,'Synthetic point exception')$$,'J05 point change moves one lesson to another day');
select is((select calendar_date from public.class_occurrences where id=(select id from ids where key='point')),current_date+5,'J05 displayed date uses persisted exception');
select throws_ok($$select public.save_occurrence_attendance((select id from ids where key='point'),pg_temp.id(32),'PRESENT')$$,'P0001','FUTURE_ATTENDANCE','J05 future point exception cannot be marked attended today');
select is((select local_start_time from public.class_occurrences where class_id=(select id from ids where key='classParallel') and local_date=current_date+6 and status='planned'),time '10:00','J05 point change preserves neighboring lessons');
select lives_ok($$select public.save_operational_membership((select id from ids where key='classParallel'),pg_temp.id(32),current_date+4,null,array['monday','tuesday','wednesday','thursday','friday','saturday','sunday']::public.class_weekday[],null,(select id from public.class_memberships where class_id=(select id from ids where key='classA') and patient_id=pg_temp.id(32)))$$,'J01 transfer versions the original membership');
select is((select effective_to from public.class_memberships where class_id=(select id from ids where key='classA') and patient_id=pg_temp.id(32)),current_date+4,'J01 transfer preserves previous attendance period');
select lives_ok($$select public.end_operational_membership((select id from public.class_memberships where class_id=(select id from ids where key='classParallel') and patient_id=pg_temp.id(32)),current_date+7)$$,'J01 membership can end by effective date');
select lives_ok($$select public.save_agenda_exception('leave',pg_temp.id(20),pg_temp.id(40),((current_date+8)+time '00:00') at time zone 'America/Sao_Paulo',((current_date+9)+time '00:00') at time zone 'America/Sao_Paulo','Synthetic professional leave')$$,'J04 leave records affected lessons for explicit substitution');
select throws_ok($$select public.save_clinic_user(pg_temp.id(3),jsonb_build_object('name','SHOULD_ROLLBACK','unitIds',jsonb_build_array(pg_temp.id(22))))$$,'P0001','UNIT_FORBIDDEN','user scope error rolls back complete compound change');
select is((select name from public.profiles where id=pg_temp.id(3)),'Synthetic role 3','user name stayed unchanged after failed unit update');
select throws_ok($$select public.save_professional(jsonb_build_object('name','SHOULD_ROLLBACK','unitIds',jsonb_build_array(pg_temp.id(22))))$$,'P0001','UNIT_FORBIDDEN','professional create rejects foreign unit atomically');
select is((select count(*) from public.professionals where name='SHOULD_ROLLBACK'),0::bigint,'failed professional create leaves no orphan');
select lives_ok($$insert into ids values('unassigned',(pg_temp.class_input(null,pg_temp.id(20),'16:00')->'class'->>'id')::uuid)$$,'J01 preserve approved creation without assigned professional');
select lives_ok($$select public.update_operational_group((select id from ids where key='unassigned'),jsonb_build_object('effective_from',current_date+2,'starts_at','16:00','duration_minutes',60,'professional_id',pg_temp.id(42),'capacity',1))$$,'J01 assign responsible professional later by explicit effective date');
select set_config('request.jwt.claim.sub',pg_temp.id(3)::text,true);
select is((select count(*) from storage.objects where bucket_id='clinical-files'),0::bigint,'reception cannot read clinical objects through direct Storage RLS');

reset role;
select set_config('request.jwt.claim.sub','',true);
set constraints all immediate;
select * from finish();
rollback;
